Hay una serie de productos marcados con un determinado precio y que pertenecen a distintas Categorías.
¿Qué obtiene la siguiente consulta?
var categorias =
    from p in productos
    group p by p.Categoria into g
    select new
    {
        Categoria = g.Key,
        ProductoMedio = g.Average()
    };

¿Qué obtiene la siguiente consulta?
var seleccion =
    from c in categorias
    join p in productos
        on c equals p.Categoria
        into ps
    from p in ps.DefaultIfEmpty()
    select new
    {
        Categoria = c,
        Producto = p == null ? "No hay productos" : p.Nombre
    };

